do $reylo$ declare s regclass := pg_get_serial_sequence('public.events', 'id'); stands numeric; goal numeric := 5000000; reach numeric; low numeric; high numeric; c record; begin select seqmin, seqmax into low, high from pg_sequence where seqrelid = s; execute format('select case when is_called then last_value::numeric + (1) else last_value end from %s', s) into stands; for c in select d.refobjid::regclass as rel, a.attname, a.atttypid in ('int2'::regtype, 'int4'::regtype, 'int8'::regtype) as plain from pg_depend d join pg_attribute a on a.attrelid = d.refobjid and a.attnum = d.refobjsubid where d.classid = 'pg_class'::regclass and d.objid = s and d.refclassid = 'pg_class'::regclass and d.deptype in ('a', 'i') union all select ad.adrelid::regclass, a.attname, a.atttypid in ('int2'::regtype, 'int4'::regtype, 'int8'::regtype) and r.relkind in ('r', 'p') and pg_get_expr(ad.adbin, ad.adrelid) = format('nextval(%L::regclass)', s::text) from pg_depend d join pg_attrdef ad on ad.oid = d.objid join pg_attribute a on a.attrelid = ad.adrelid and a.attnum = ad.adnum join pg_class r on r.oid = ad.adrelid where d.classid = 'pg_attrdef'::regclass and d.refclassid = 'pg_class'::regclass and d.refobjid = s union all select null, null, false from pg_depend d where d.classid = 'pg_type'::regclass and d.refclassid = 'pg_class'::regclass and d.refobjid = s loop if not c.plain then return; end if; execute format('select max(%I)::numeric + 1 from %s', c.attname, c.rel) into reach; if reach > goal and reach between low and high then goal := reach; end if; end loop; if goal > stands and goal between low and high then perform setval(s, goal::bigint, false); end if; end $reylo$;
alter table events alter column id set start with 5000000;
